//! What a prover and a verifier use: the approved circuits, a key pack, and the verifier's trust
//! list.
//!
//! The approved circuits are pinned in `approved.rs` (generated by `scripts/build_circuits.py`) by
//! the SHA-256 of their r1cs and sym only, so any trusted setup of them can be used. A key is
//! checked against phase 1 ([`Ceremony::verify_key`]) the first time its circuit is used, whether
//! to prove or to verify. Proving needs nothing more; verifying also needs the key to be authorized
//! by the [`Trust`] list, by setup id or key id.

use std::collections::BTreeMap;
use std::sync::{Arc, Mutex};

use crate::digest::{hex, sha256};
use crate::keys::{KeyId, KeyPack, Trust};
use crate::{
    approved::APPROVED, zkey, Ceremony, Circuit, Groth16Error, Result, Source, VerifyingKey,
};

/// The pinned identity of one approved circuit.
pub(crate) struct Approved {
    pub name: &'static str,
    pub r1cs_sha256: &'static str,
    pub sym_sha256: &'static str,
}

pub(crate) fn approved(name: &str) -> Result<&'static Approved> {
    APPROVED
        .iter()
        .find(|a| a.name == name)
        .ok_or_else(|| Groth16Error::Unapproved(name.into()))
}

/// Names of every approved circuit.
pub fn circuits() -> impl Iterator<Item = &'static str> {
    APPROVED.iter().map(|a| a.name)
}

/// The bytes of `<name>.<extension>` (`r1cs` or `sym`) from `source`, refused unless they hash to
/// the approved circuit's pin.
pub(crate) fn pinned(source: &dyn Source, name: &str, extension: &str) -> Result<Arc<[u8]>> {
    let pins = approved(name)?;
    let pin = match extension {
        "r1cs" => pins.r1cs_sha256,
        _ => pins.sym_sha256,
    };
    let bytes = source.read(&format!("{name}.{extension}"))?;
    if hex(&sha256(&bytes)) == pin {
        Ok(bytes)
    } else {
        Err(Groth16Error::Format(format!(
            "{name}.{extension} is not the approved artifact"
        )))
    }
}

struct Inner {
    ceremony: Ceremony,
    keys: KeyPack,
    setup_id: KeyId,
    trust: Trust,
    /// Circuits whose key has passed [`Ceremony::verify_key`], with the key's id.
    checked: Mutex<BTreeMap<String, KeyId>>,
}

/// A key pack ready to prove and, where trusted, to verify.
#[derive(Clone)]
pub struct Setup(Arc<Inner>);

impl Setup {
    pub fn new(ceremony: Ceremony, keys: KeyPack, trust: Trust) -> Result<Self> {
        Ok(Self(Arc::new(Inner {
            setup_id: keys.setup_id()?,
            ceremony,
            keys,
            trust,
            checked: Mutex::default(),
        })))
    }

    pub fn setup_id(&self) -> KeyId {
        self.0.setup_id
    }

    pub fn keys(&self) -> &KeyPack {
        &self.0.keys
    }

    pub fn trust(&self) -> &Trust {
        &self.0.trust
    }

    pub fn ceremony(&self) -> &Ceremony {
        &self.0.ceremony
    }

    /// Circuit `name`'s key and id, verified against phase 1 on first use.
    fn checked_key(&self, name: &str) -> Result<(&[u8], KeyId)> {
        let zkey = self.0.keys.get(name).ok_or_else(|| {
            Groth16Error::Missing(format!("the key pack has no key for `{name}`"))
        })?;
        let mut checked = self
            .0
            .checked
            .lock()
            .unwrap_or_else(std::sync::PoisonError::into_inner);
        let id = match checked.get(name) {
            Some(id) => *id,
            None => {
                let id = self.0.ceremony.verify_key(name, zkey)?.key_id;
                *checked.entry(name.to_owned()).or_insert(id)
            }
        };
        Ok((zkey, id))
    }

    /// Circuit `name` with this setup's key, for proving.
    pub fn circuit(&self, name: &str) -> Result<Circuit> {
        let (zkey, _) = self.checked_key(name)?;
        let r1cs = self.0.ceremony.artifact(name, "r1cs")?;
        let sym = self.0.ceremony.artifact(name, "sym")?;
        let sym = std::str::from_utf8(&sym)
            .map_err(|_| Groth16Error::Format(format!("{name}.sym is not UTF-8")))?;
        Circuit::new(name, &r1cs, sym, zkey)
    }

    /// Whether the trust list authorizes circuit `name`'s key to verify proofs.
    pub fn is_trusted(&self, name: &str) -> Result<bool> {
        let (_, id) = self.checked_key(name)?;
        Ok(self.0.trust.allows(&self.0.setup_id, &id))
    }

    /// Circuit `name`'s verifying key, refused unless the trust list authorizes it.
    pub fn verifying_key(&self, name: &str) -> Result<VerifyingKey> {
        let (zkey, id) = self.checked_key(name)?;
        if !self.0.trust.allows(&self.0.setup_id, &id) {
            return Err(Groth16Error::Untrusted(format!(
                "{name}: neither setup {} nor key {id} is in the trust list",
                self.0.setup_id
            )));
        }
        Ok(VerifyingKey::new(&zkey::parse(zkey)?.proving_key.vk))
    }
}
